# ---- 1.2 Maxima set ---------------------------------------------------------

def lexicographic(p1, p2):
    """Given: True iff p1 is before p2 in the lexicographic order (x first, then y)."""
    if (p1[0] < p2[0]):
        return True
    elif (p1[0] == p2[0]):
        return p1[1] <= p2[1]
    return False


